const dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('cricavo',1);req.onupgradeneeded=()=>req.result.createObjectStore('matches',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
export async function listMatches(){const db=await dbPromise;return new Promise((resolve,reject)=>{const req=db.transaction('matches').objectStore('matches').getAll();req.onsuccess=()=>resolve(req.result.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)));req.onerror=()=>reject(req.error)})}
export async function addMatchCopies(matches){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('matches','readwrite'),store=tx.objectStore('matches');for(const match of matches)store.add(match);tx.oncomplete=()=>resolve();tx.onabort=tx.onerror=()=>reject(tx.error||Error('Restoring matches failed'));})}
export async function saveMatch(match,expectedRevision){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('matches','readwrite'),store=tx.objectStore('matches');let reason;const req=store.get(match.id);req.onsuccess=()=>{if((req.result?.revision??null)!==expectedRevision){reason=Error('This match changed in another tab. Reload the latest score before continuing.');tx.abort();return}store.put(match)};tx.oncomplete=()=>resolve(match);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(reason||tx.error||Error('Saving failed'))})}
